import{_ as n,C as o,o as h,c as e,j as i,a as r,E as s,a3 as t}from"./chunks/framework.C6R8kWFE.js";const A=JSON.parse('{"title":"6-dars (Mentor). Kompyuter xavfsizligi va antivirus dasturlari","description":"","frontmatter":{"title":"6-dars (Mentor). Kompyuter xavfsizligi va antivirus dasturlari","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"8-sinf (Foundation)","link":"/mentor/8-sinf-cs/"},"week":{"n":2,"link":"/mentor/8-sinf-cs/hafta-02/"},"g":6,"title":"Kompyuter xavfsizligi va antivirus dasturlari","lead":"Kompyuterni kiberxatarlardan himoyalash, zararli dasturlar turlari, antiviruslarning ishlash sirlari hamda mustahkam parollar yaratish madaniyati.","slide":"/slaydlar/8-sinf-cs/hafta-02/dars-3.html","test":"/slaydlar/8-sinf-cs/hafta-02/dars-3-test.html","student_link":"/8-sinf-cs/hafta-02/dars-3","tabs":[{"g":4,"link":"/mentor/8-sinf-cs/hafta-02/dars-1","current":false},{"g":5,"link":"/mentor/8-sinf-cs/hafta-02/dars-2","current":false},{"g":6,"link":"/mentor/8-sinf-cs/hafta-02/dars-3","current":true}],"prev":{"g":5,"title":"Internet, brauzerlar va elektron pochta bilan ishlash","link":"/mentor/8-sinf-cs/hafta-02/dars-2"},"next":null}},"headers":[],"relativePath":"mentor/8-sinf-cs/hafta-02/dars-3.md","filePath":"mentor/8-sinf-cs/hafta-02/dars-3.md"}'),d={name:"mentor/8-sinf-cs/hafta-02/dars-3.md"},u={class:"blk"},g={id:"_1-dars-rejasi",tabindex:"-1"},m={class:"blk"},k={id:"_2-dars-konspekti",tabindex:"-1"},y={class:"blk"},v={id:"_3-amaliy-topshiriqlar-va-yechimlari",tabindex:"-1"},b={class:"blk"},f={id:"_4-tezkor-nazorat-savollari-javoblari-bilan",tabindex:"-1"};function c(q,a,z,p,x,_){const l=o("Icon");return h(),e("div",null,[a[12]||(a[12]=i("p",null,[i("strong",null,"Hafta:"),r(" 2 · "),i("strong",null,"Davomiyligi:"),r(" 80 daqiqa · "),i("strong",null,"Turi:"),r(" nazariya + amaliy mashg'ulot · "),i("strong",null,"I-bob"),r(", 6-dars")],-1)),i("div",u,[i("h2",g,[s(l,{name:"file-text"}),a[0]||(a[0]=r(" 1. Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#_1-dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> 1. Dars rejasi"'},"​",-1))]),a[2]||(a[2]=t('<p><strong>Maqsad:</strong> o&#39;quvchilarda kompyuter va axborot xavfsizligi tushunchalari, zararli dasturlar (malware: virus, trojan, spyware, ransomware, worm), antivirus tizimlarining ishlash mexanizmlari (skanerlash, karantin, real-vaqt himoyasi), kuchli parollar yaratish va 2FA (ikki bosqichli autentifikatsiya) hamda tashqi xotira (fleshka) va internetdan xavfsiz foydalanish bo&#39;yicha mustahkam ko&#39;nikmalarni shakllantirish.</p><p><strong>Kutiladigan natija:</strong></p><ul><li>Kompyuter xavfsizligi va kibergigiyena asosiy tamoyillarini tushuntira oladi.</li><li>Zararli dasturlar tasnifini (virus, troyan oti, ayg&#39;oqchi dastur, shifrlash virusi/tovlamachi) biladi va ularning xavfini farqlaydi.</li><li>Antivirus dasturlari (Windows Defender va boshqalar) qanday ishlashini (imzo tahlili, evristik tahlil, karantin) tushunadi va amalda skanerlashni bajara oladi.</li><li>Xavfsiz va buzilmas parol tuzish qoidalariga rioya qiladi, 2FA tizimining mohiyatini tushunadi.</li><li>Fleshka, elektron pochta va internetdan foydalanishda xavfsizlik choralarini to&#39;g&#39;ri qo&#39;llaydi.</li></ul><table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Mazmun</th></tr></thead><tbody><tr><td>0–10 daq</td><td>Takrorlash va kirish</td><td>O&#39;tgan darsni takrorlash (brauzerlar va email). Muammoli vaziyat: «Kompyuter to&#39;satdan qotib, barcha fayllar ochilmay qolsa yoki ekranda pul talab qilinsa, nima qilish kerak?»</td></tr><tr><td>10–30 daq</td><td>Yangi mavzu: Nazariya</td><td>Zararli dasturlar (Malware) turlari, antiviruslarning ishlash tamoyillari, parollar madaniyati va 2FA, fleshkalar xavfsizligi</td></tr><tr><td>30–35 daq</td><td>Tanaffus</td><td>Harakatli tanaffus</td></tr><tr><td>35–65 daq</td><td>Amaliy mashg&#39;ulot</td><td>Windows Security orqali tezkor va to&#39;liq skanerlash, fleshkani tekshirish, parol kuchini baholash algoritmi</td></tr><tr><td>65–75 daq</td><td>Tezkor nazorat</td><td>5 ta savol-javob va vaziyatli (case-study) tahlil</td></tr><tr><td>75–80 daq</td><td>Xulosa va uyga vazifa</td><td>Muhim qoidalarni jamlash va uyga vazifani tushuntirish</td></tr></tbody></table><hr>',5))]),i("div",m,[i("h2",k,[s(l,{name:"file-text"}),a[3]||(a[3]=r(" 2. Dars konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#_2-dars-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> 2. Dars konspekti"'},"​",-1))]),a[5]||(a[5]=t('<h3 id="_2-1-kompyuter-xavfsizligi-va-kibergigiyena-tushunchasi" tabindex="-1">2.1. Kompyuter xavfsizligi va kibergigiyena tushunchasi <a class="header-anchor" href="#_2-1-kompyuter-xavfsizligi-va-kibergigiyena-tushunchasi" aria-label="Permalink to &quot;2.1. Kompyuter xavfsizligi va kibergigiyena tushunchasi&quot;">​</a></h3><p><strong>Kompyuter xavfsizligi (Computer Security)</strong> — bu kompyuter apparat vositalari, dasturiy ta&#39;minot va unda saqlanayotgan shaxsiy ma&#39;lumotlarni ruxsatsiz kirish, o&#39;g&#39;irlanish, buzilish yoki yo&#39;qotilishdan himoya qilish choralari majmuasidir.</p><p>Axborot xavfsizligining 3 ta klassik ustuni (CIA triada):</p><ol><li><strong>Maxfiylik (Confidentiality):</strong> Ma&#39;lumotlarni faqat ruxsati bor insonlar ko&#39;ra olishi (parol, shifrlash).</li><li><strong>Yaxlitlik (Integrity):</strong> Ma&#39;lumotlarning buzilmasdan, ruxsatsiz o&#39;zgartirilmasdan asl holicha saqlanishi.</li><li><strong>Mavjudlik (Availability):</strong> Kerakli paytda tizim va ma&#39;lumotlarga to&#39;siqsiz kirish imkoniyatining bo&#39;lishi.</li></ol><h3 id="_2-2-zararli-dasturlar-malware-turlari" tabindex="-1">2.2. Zararli dasturlar (Malware) turlari <a class="header-anchor" href="#_2-2-zararli-dasturlar-malware-turlari" aria-label="Permalink to &quot;2.2. Zararli dasturlar (Malware) turlari&quot;">​</a></h3><p>Zararli dasturiy ta&#39;minot (<strong>Malware</strong> — Malicious Software) — kompyuter tizimiga zarar yetkazish, shaxsiy ma&#39;lumotlarni o&#39;g&#39;irlash yoki foydalanuvchini boshqarishdan mahrum qilish maqsadida yozilgan dasturlardir.</p><p>Asosiy turlari:</p><ol><li><strong>Klassik viruslar (Virus):</strong> Boshqa qonuniy fayllar yoki dasturlarga yopishib olib, ular ishga tushganda o&#39;z kodini ko&#39;paytiruvchi va tizimni zararlaydigan dasturlar.</li><li><strong>Chuvalchanglar (Worm):</strong> Foydalanuvchining aralashuvisiz, lokal tarmoq yoki internet orqali o&#39;z-o&#39;zidan bir kompyuterdan ikkinchisiga tarqaluvchi zararli dasturlar.</li><li><strong>Troyan oti (Trojan Horse):</strong> O&#39;zini foydali yoki bepul o&#39;yin/dastur qilib ko&#39;rsatib, kompyuterga yashirin kirib oluvchi va jinoyatchiga tizimni masofadan boshqarish imkonini beruvchi zararli kod.</li><li><strong>Ayg&#39;oqchi dasturlar (Spyware):</strong> Foydalanuvchining klaviaturada nimalarni terayotganini (login, parol, karta raqami) yashirincha yozib olib, tajovuzkorga jo&#39;natuvchi dasturlar (Keyloggerlar).</li><li><strong>Tovlamachi / Shifrlash viruslari (Ransomware):</strong> Kompyuterdagi barcha fotosurat, hujjat va fayllarni shifrlab (qulflab) qo&#39;yib, ularni ochish uchun foydalanuvchidan kriptovalyutada to&#39;lov talab qiluvchi eng xavfli viruslar (masalan: WannaCry).</li><li><strong>Reklama dasturlari (Adware):</strong> Ekranda doimiy ravishda noqulay va keraksiz reklama bannerlarini chiqarib chalg&#39;ituvchi dasturlar.</li></ol><h3 id="_2-3-antivirus-dasturlari-va-ularning-ishlash-mexanizmi" tabindex="-1">2.3. Antivirus dasturlari va ularning ishlash mexanizmi <a class="header-anchor" href="#_2-3-antivirus-dasturlari-va-ularning-ishlash-mexanizmi" aria-label="Permalink to &quot;2.3. Antivirus dasturlari va ularning ishlash mexanizmi&quot;">​</a></h3><p><strong>Antivirus</strong> — bu zararli dasturlarni aniqlash, ularning faoliyatini to&#39;xtatish, zararlangan fayllarni davolash yoki o&#39;chirish uchun xizmat qiluvchi himoya dasturidir.</p><p>Eng mashhur antiviruslar:</p><ul><li><strong>Windows Security (Microsoft Defender):</strong> Windows 10 va 11 tizimlariga integratsiya qilingan, bepul va yetarli darajada kuchli antivirus.</li><li><strong>Kaspersky, ESET NOD32, Bitdefender, Avast, Norton:</strong> Kengaytirilgan imkoniyatlarga ega tijoriy antivirus majmualari.</li></ul><p>Antivirusning ishlash bosqichlari:</p><ol><li><strong>Real vaqt rejimida himoya (Real-time Protection):</strong> Har safar biror dastur ishga tushganda yoki fayl yuklanganda, antivirus uni fonda tekshiradi.</li><li><strong>Imzo (Signature) tahlili:</strong> Antivirus bazasidagi ma&#39;lum viruslarning raqamli izlari (xesh kodlari) bilan yangi fayllarni solishtirish.</li><li><strong>Evristik tahlil (Heuristic Analysis):</strong> Dasturning shubhali xatti-harakatlarini (masalan, tizim registrini o&#39;zgartirish, tizim fayllarini shifrlashga urinish) tahlil qilib, hali bazada yo&#39;q yangi viruslarni aniqlash.</li><li><strong>Karantin (Quarantine):</strong> Shubhali faylni maxsus izolyatsiyalangan papkaga ko&#39;chirib, uning ishlashini to&#39;liq bloklash.</li><li><strong>Doimiy yangilanish (Definitions Update):</strong> Har kuni dunyoda minglab yangi viruslar paydo bo&#39;ladi. Shu sababli antivirus bazasi muntazam ravishda yangilanib turishi shart.</li></ol><h3 id="_2-4-parol-madaniyati-va-2fa-ikki-bosqichli-himoya" tabindex="-1">2.4. Parol madaniyati va 2FA (Ikki bosqichli himoya) <a class="header-anchor" href="#_2-4-parol-madaniyati-va-2fa-ikki-bosqichli-himoya" aria-label="Permalink to &quot;2.4. Parol madaniyati va 2FA (Ikki bosqichli himoya)&quot;">​</a></h3><ul><li><strong>Kuchli parol qoidalari:</strong><ul><li>Kamida 12 ta belgidan iborat bo&#39;lishi kerak.</li><li>Katta va kichik harflar (<code>A-Z</code>, <code>a-z</code>), raqamlar (<code>0-9</code>) va maxsus belgilar (<code>!@#$%^&amp;*</code>) aralashmasi bo&#39;lishi lozim.</li><li>Ism, tug&#39;ilgan sana, <code>123456</code>, <code>qwerty</code> yoki telefon raqami kabi oson topiladigan so&#39;zlardan foydalanmaslik.</li><li>Turli xil saytlar uchun bitta paroldan foydalanmaslik (har bir xizmat uchun alohida parol).</li></ul></li><li><strong>2FA (Two-Factor Authentication / Ikki bosqichli autentifikatsiya):</strong><ul><li>Akkauntga kirishda faqat login va parolni bilish yetarli emas. Tizim ikkinchi omilni — telefoningizga kelgan bir martalik SMS kodni yoki autentifikator ilovasidagi (Google Authenticator) 6 xonali kodni talab qiladi.</li><li>2FA yoqilgan bo&#39;lsa, hatto parolingiz o&#39;g&#39;irlangan taqdirda ham jinoyatchi hisobingizga kira olmaydi.</li></ul></li></ul><h3 id="_2-5-fleshka-va-tashqi-xotira-xavfsizligi" tabindex="-1">2.5. Fleshka va tashqi xotira xavfsizligi <a class="header-anchor" href="#_2-5-fleshka-va-tashqi-xotira-xavfsizligi" aria-label="Permalink to &quot;2.5. Fleshka va tashqi xotira xavfsizligi&quot;">​</a></h3><p>USB fleshkalar orqali virus yuqishining oldini olish qoidalari:</p><ol><li>Fleshkani kompyuterga ulagach, darhol unga kirmasdan, sichqonchaning o&#39;ng tugmasini bosib «Scan with Microsoft Defender» (Antivirus bilan tekshirish) amalini bajaring.</li><li>Windows tizimida <strong>Autorun (Avto-ishga tushirish)</strong> funksiyasi o&#39;chirilgan bo&#39;lishi kerak (zamonaviy Windows versiyalarida xavfsizlik uchun u avtomatik bloklanadi).</li><li>Fleshkada g&#39;alati <code>.lnk</code> (yorliq / shortcut) yoki <code>.vbs</code> kengaytmali fayllar paydo bo&#39;lsa, ularni aslo bosmang.</li></ol><hr>',20))]),i("div",y,[i("h2",v,[s(l,{name:"file-text"}),a[6]||(a[6]=r(" 3. Amaliy topshiriqlar va yechimlari ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#_3-amaliy-topshiriqlar-va-yechimlari","aria-label":'Permalink to "<Icon name="file-text" /> 3. Amaliy topshiriqlar va yechimlari"'},"​",-1))]),a[8]||(a[8]=t('<h3 id="_1-topshiriq-windows-security-dasturini-ishga-tushirish-va-tezkor-skanerlash" tabindex="-1">1-topshiriq. Windows Security dasturini ishga tushirish va tezkor skanerlash <a class="header-anchor" href="#_1-topshiriq-windows-security-dasturini-ishga-tushirish-va-tezkor-skanerlash" aria-label="Permalink to &quot;1-topshiriq. Windows Security dasturini ishga tushirish va tezkor skanerlash&quot;">​</a></h3><p><strong>Vazifa:</strong> Windows 10/11 tizimida o&#39;rnatilgan Microsoft Defender dasturini oching, oxirgi tekshiruv vaqtini ko&#39;ring va «Quick scan» (Tezkor skanerlash) amalini bajaring. <strong>Yechim:</strong></p><ul><li><code>Win + S</code> qidiruviga «Windows Security» yoki «Xavfsizlik» deb yozib dastur ochiladi.</li><li>«Virus &amp; threat protection» (Viruslar va tahdidlardan himoyalanish) bo&#39;limi tanlanadi.</li><li>«Quick scan» tugmasi bosiladi. Antivirus tizimning eng nozik joylarini (xotira, tizim papkalari) 1-3 daqiqa ichida tekshiradi va natijani ko&#39;rsatadi.</li></ul><h3 id="_2-topshiriq-fleshkani-antivirus-orqali-maxsus-tekshirish" tabindex="-1">2-topshiriq. Fleshkani antivirus orqali maxsus tekshirish <a class="header-anchor" href="#_2-topshiriq-fleshkani-antivirus-orqali-maxsus-tekshirish" aria-label="Permalink to &quot;2-topshiriq. Fleshkani antivirus orqali maxsus tekshirish&quot;">​</a></h3><p><strong>Vazifa:</strong> Tashqi USB fleshkani kompyuterga ulang va faqat shu fleshkaning o&#39;zini antivirus orqali to&#39;liq tekshirish usulini ko&#39;rsating. <strong>Yechim:</strong></p><ul><li>«This PC» (Mening kompyuterim) oynasi ochiladi.</li><li>Ulangan USB fleshka belgisi ustiga sichqonchaning o&#39;ng tugmasi bosiladi.</li><li>Kontekst menyusidan «Scan with Microsoft Defender...» tanlanadi.</li><li>Tekshiruv yakunlanib, «No current threats» (Tahdidlar aniqlanmadi) xabari olingach, fleshkadan xavfsiz foydalanish mumkin.</li></ul><h3 id="_3-topshiriq-kuchli-va-esda-qoladigan-parol-yaratish" tabindex="-1">3-topshiriq. Kuchli va esda qoladigan parol yaratish <a class="header-anchor" href="#_3-topshiriq-kuchli-va-esda-qoladigan-parol-yaratish" aria-label="Permalink to &quot;3-topshiriq. Kuchli va esda qoladigan parol yaratish&quot;">​</a></h3><p><strong>Vazifa:</strong> O&#39;zingiz uchun buzilmas, kamida 12 belgidan iborat, katta-kichik harf, raqam va maxsus belgi qatnashgan kuchli parol formulasini ishlab chiqing (Masalan, shior yoki jumlalar asosida). <strong>Yechim:</strong></p><ul><li>Oddiy so&#39;zlardan qochish uchun ibora tanlanadi: <em>«Men maktabda 8-sinfda o&#39;qiyman va ITni sevaman!»</em></li><li>Har bir so&#39;zning bosh harfi olinadi: <code>M m 8-s o&#39; v IT s!</code> -&gt; <code>Mm8-so&#39;vITs!</code></li><li>Parol shakli: <code>Mm8@sov_IT#2026</code> (15 ta belgi, esda qolishi oson, lekin maxsus dasturlar bilan ham yillab buzib bo&#39;lmaydi).</li></ul><hr>',10))]),i("div",b,[i("h2",f,[s(l,{name:"file-text"}),a[9]||(a[9]=r(" 4. Tezkor nazorat savollari (javoblari bilan) ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#_4-tezkor-nazorat-savollari-javoblari-bilan","aria-label":'Permalink to "<Icon name="file-text" /> 4. Tezkor nazorat savollari (javoblari bilan)"'},"​",-1))]),a[11]||(a[11]=t("<ol><li><strong>Savol:</strong> Ransomware (shifrlash virusi) kompyuterga qanday zarar keltiradi? <strong>Javob:</strong> U kompyuterdagi barcha fotosuratlar, hujjatlar va fayllarni shifrlab qulflab qo&#39;yadi va ochish uchun foydalanuvchidan to&#39;lov (tovlamachilik) talab qiladi.</li><li><strong>Savol:</strong> Troyan oti (Trojan Horse) virusidan nima bilan farqlanadi? <strong>Javob:</strong> Virus boshqa fayllarni zararlab o&#39;zini ko&#39;paytiradi. Troyan esa foydali dastur niqobi ostida tizimga kirib, tajovuzkorga masofadan boshqarish imkonini beradi (o&#39;zini ko&#39;paytirmaydi).</li><li><strong>Savol:</strong> Antivirusdagi «Karantin» (Quarantine) nima vazifani bajaradi? <strong>Javob:</strong> Karantin shubhali yoki zararlangan faylni maxsus xavfsiz izolyatsiyaga olib, uning tizimga ta&#39;sir o&#39;tkazishini to&#39;xtatadi.</li><li><strong>Savol:</strong> 2FA (Ikki bosqichli autentifikatsiya) nima uchun kerak? <strong>Javob:</strong> Agar parol o&#39;g&#39;irlansa ham, ikkinchi omil (telefon orqali tasdiqlash) bo&#39;lmasa begona shaxs akkauntga kira olmaydi.</li><li><strong>Savol:</strong> Nima uchun kompyuterga yangi ulangan fleshkani darhol ochmasdan, avval skaner qilish kerak? <strong>Javob:</strong> Begona kompyuterlardan fleshkaga yashirin avto-ishga tushuvchi viruslar yozilgan bo&#39;lishi mumkin. Skanerlash ularni aniqlab zararsizlantiradi.</li></ol>",1))])])}const S=n(d,[["render",c]]);export{A as __pageData,S as default};
